import {join,resolve} from 'node:path';
import {staticOrigin} from './static-origin.mjs';
import {inventory} from '../../scripts/build-pages-artifact.mjs';
assert.equal(process.env.GITHUB_ACTIONS,'true','Use only the authorized Actions runner');
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_PACKAGE);
const artifact=resolve(process.env.PAGES_ARTIFACT),reportDir=resolve(process.env.BROWSER_REPORT);await mkdir(reportDir,{recursive:true});
const git=(...a)=>execFileSync('git',a),sha=b=>createHash('sha256').update(b).digest('hex');
const fixture=JSON.parse(await readFile(new URL('./fixtures/short-apply-physical-details.json',import.meta.url),'utf8')),messages=fixture.messages;assert.equal(Object.keys(messages).length,20);
const diagnostic=process.env.GITHUB_EVENT_NAME==='push';
const report={head:process.env.TESTED_HEAD,base:process.env.TESTED_BASE,publishedMain:diagnostic?fixture.publishedMain:process.env.TESTED_BASE,priorWipHead:fixture.priorWipHead,checkout:git('rev-parse','HEAD').toString().trim(),diagnostic,started:new Date().toISOString(),files:{},rows:[],observations:[],captureGeometry:[],mutations:[],external:[],limits:['Chromium320/1280 fixtures only; no physical-device or native-speaker certification.','Existing full40 screening flows already assert the isolated conditional error. This adds the missing personal error/hint/focus fragments, keyboard, whitespace and recovery checks. No application delivery.','Fresh contexts with service workers blocked; no new offline acceptance.']};
if(diagnostic){assert.equal(report.checkout,report.head);assert.equal(git('rev-parse','HEAD^').toString().trim(),report.base);}else{assert.deepEqual(git('show','-s','--format=%P','HEAD').toString().trim().split(' '),[report.base,report.head]);assert.equal(git('rev-parse','HEAD^{tree}').toString().trim(),git('rev-parse',report.head+'^{tree}').toString().trim());}
for(const {path:p}of inventory(artifact)){
 const source=p.startsWith('tools/coordinator/')?'coordinator-demo/'+p.split('/').at(-1):p,b=await readFile(join(artifact,p));assert.deepEqual(b,git('show',`${report.head}:${source}`));if(diagnostic)assert.deepEqual(b,git('show',`${fixture.priorWipHead}:${source}`),'All diagnostic publication inputs must equal the preserved WIP: '+p);const publishedExact=b.equals(git('show',`${report.publishedMain}:${source}`));assert.equal(publishedExact,p!=='docs/primserv-roadmap.md','Only the canonical WIP may differ from published runtime: '+p);report.files[p]={source,bytes:b.length,sha256:sha(b),publishedExact};
}
assert.equal(Object.keys(report.files).length,317);
const serveRoot=await mkdtemp(join(tmpdir(),'primserv-physical-details-'));await symlink(artifact,join(serveRoot,'kiris-jobs'),'dir');const origin=staticOrigin(serveRoot),base='http://127.0.0.1:4173/kiris-jobs/';let browser;
async function data(page){return page.evaluate(()=>JSON.parse(localStorage.getItem('citronex_screening_application_v17')).data);}
async function language(page,lang){await page.locator('[data-action="language"]').click();await page.locator('#languageSearch').fill(lang);await page.locator(`[data-language="${lang}"]`).click();await page.locator('[data-recruiter="yana"]').click();await page.locator('#physicalDetails').waitFor();assert.equal(await page.locator('html').getAttribute('lang'),lang);}
async function invalid(page,lang){await page.locator('[data-action="next"]').click();await page.waitForFunction(()=>document.activeElement?.id==='physicalDetails');assert.equal(await page.locator('.field-error').count(),1);assert.equal(await page.locator('[aria-invalid="true"]').count(),1);assert.equal(await page.locator('#physicalDetails-error').innerText(),messages[lang].required);assert.equal(await page.locator('#physicalDetails').getAttribute('aria-invalid'),'true');assert.equal(await page.locator('#physicalDetails').getAttribute('aria-describedby'),'physicalDetails-error');assert.equal(await page.locator('.progress-meta strong').innerText(),'2 / 3');}
async function shot(page,file){
 const measure=()=>page.locator('#physicalDetails').evaluate(n=>{const r=n.closest('.field').getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height,scrollY};});
 for(let attempt=1;attempt<=3;attempt++){
  await page.locator('#physicalDetails').evaluate(n=>{n.closest('.field').scrollIntoView({block:'center',behavior:'instant'});delete window.__physicalCapture;});await page.waitForFunction(()=>{const r=document.getElementById('physicalDetails').closest('.field').getBoundingClientRect(),key=[scrollY,r.x,r.y,r.width,r.height].join(':');if(window.__physicalCapture?.key!==key)window.__physicalCapture={key,since:performance.now()};return performance.now()-window.__physicalCapture.since>=180;},{},{polling:'raf',timeout:2500});
  const before=await measure(),vp=page.viewportSize(),x=Math.floor(before.x)-6,y=Math.floor(before.y)-6,right=Math.ceil(before.x+before.width)+6,bottom=Math.ceil(before.y+before.height)+6;assert(x>=0&&y>=0&&right<=vp.width&&bottom<=vp.height,'Complete field/hint/error/focus must fit');const clip={x,y,width:right-x,height:bottom-y},b=await page.screenshot({clip}),after=await measure(),stable=Object.keys(before).every(k=>Math.abs(before[k]-after[k])<0.1);report.captureGeometry.push({file,attempt,before,after,clip,stable});if(stable){await writeFile(join(reportDir,file),b);return;}await writeFile(join(reportDir,file.replace('.png',`.unstable-${attempt}.png`)),b);
 }
 throw Error('Conditional field moved in all bounded captures');
}
async function run({width,lang}){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block',reducedMotion:'reduce'});ctx.setDefaultTimeout(15000);await ctx.route('**/*',r=>{const q=r.request(),u=new URL(q.url());if(!['GET','HEAD'].includes(q.method())){report.mutations.push({method:q.method(),path:u.pathname,blocked:true});return r.abort();}if(u.origin!==new URL(base).origin){report.external.push({host:u.hostname,path:u.pathname,blocked:true});return r.abort();}return r.continue();});const page=await ctx.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{
  await page.goto(base+'apply/');await page.locator('#languageSearch').fill(lang);await page.locator(`[data-language="${lang}"]`).click();await page.locator('[data-recruiter="yana"]').click();for(const[id,value]of [['firstName','QA'],['lastName','FIXTURE'],['phone','+99912345678'],['citizenship','FIXTURE'],['age','30']])await page.locator('#'+id).fill(value);await page.locator('#messenger').selectOption('telegram');await page.locator('[name="gender"][value="undisclosed"]').locator('..').click();await page.locator('[data-action="next"]').click();
  await page.locator('#location').selectOption('any');await page.locator('#stayDuration').selectOption('six');assert.equal(await page.locator('#physicalDetails').count(),0);await page.locator('[name="physicalWork"][value="yes"]').locator('..').click();const before=await data(page);assert.equal(before.physicalDetails,'');await invalid(page,lang);
  const away=lang==='en'?'ru':'en';await language(page,away);assert.deepEqual(await data(page),before);assert.equal(await page.locator('.field-error').count(),0);await invalid(page,away);await language(page,lang);assert.deepEqual(await data(page),before);await invalid(page,lang);await page.evaluate(()=>document.fonts.ready);
  const dom=await page.locator('#physicalDetails').evaluate(input=>{const field=input.closest('.field'),box=field.getBoundingClientRect(),style=getComputedStyle(input);const measure=n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n),clone=n.cloneNode(true);clone.style.cssText=`position:fixed;left:-10000px;top:0;visibility:hidden;display:block;width:${r.width}px;height:auto;max-height:none;overflow:visible;-webkit-line-clamp:unset;font:${s.font};letter-spacing:${s.letterSpacing};white-space:${s.whiteSpace};box-sizing:${s.boxSizing};`;document.body.append(clone);const naturalHeight=clone.getBoundingClientRect().height;clone.remove();const range=document.createRange();range.selectNodeContents(n);return {text:n.textContent,painted:n.checkVisibility({checkOpacity:true,checkVisibilityCSS:true}),height:r.height,naturalHeight,fit:r.height>=naturalHeight-1&&n.scrollWidth<=n.clientWidth+1&&[...range.getClientRects()].every(x=>x.left>=box.left-1&&x.right<=box.right+1)};};return {actualLang:document.documentElement.lang,direction:document.documentElement.dir,value:input.value,focused:document.activeElement===input,associated:input.getAttribute('aria-invalid')==='true'&&input.getAttribute('aria-describedby')==='physicalDetails-error',label:measure(field.querySelector('label')),hint:measure(field.querySelector('.field-hint')),error:measure(field.querySelector('.field-error')),painted:input.checkVisibility({checkOpacity:true,checkVisibilityCSS:true}),fit:document.documentElement.scrollWidth<=innerWidth+1&&box.left>=0&&box.right<=innerWidth+1&&field.scrollWidth<=field.clientWidth+1,focusShadow:style.boxShadow};});report.observations.push({width,lang,dom});for(const k of ['focused','associated','painted','fit'])assert.equal(dom[k],true,`${lang}:${k}`);assert.equal(dom.value,'');assert.equal(dom.actualLang,lang);assert.equal(dom.label.text,messages[lang].label+' *');assert.equal(dom.hint.text,messages[lang].hint);assert.equal(dom.error.text,messages[lang].required);assert([dom.label,dom.hint,dom.error].every(x=>x.painted&&x.fit));assert.notEqual(dom.focusShadow,'none');await shot(page,`physicalDetails-${width}-${lang}-field.png`);
  await page.keyboard.press('Shift+Tab');assert.equal(await page.evaluate(()=>document.activeElement?.name),'physicalWork');await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement?.id),'physicalDetails');await page.locator('#physicalDetails').fill(' \n ');assert.equal(await page.locator('.field-error').count(),0);await invalid(page,lang);await page.locator('#physicalDetails').fill('QA FIXTURE');assert.equal(await page.locator('.field-error').count(),0);assert.equal(await page.locator('#physicalDetails').getAttribute('aria-invalid'),null);assert.equal(await page.locator('#physicalDetails').getAttribute('aria-describedby'),null);await page.locator('[data-action="next"]').click();assert.equal(await page.locator('.progress-meta strong').innerText(),'3 / 3');assert.equal(await page.locator('[data-action="send"]').count(),0);await page.locator('[data-action="back"]').click();assert.equal(await page.locator('#physicalDetails').inputValue(),'QA FIXTURE');
  await page.locator('[name="physicalWork"][value="no"]').locator('..').click();assert.equal(await page.locator('#physicalDetails').count(),0);assert.deepEqual(await data(page),{...before,physicalWork:'no',physicalDetails:''});await page.locator('[name="physicalWork"][value="yes"]').locator('..').click();assert.equal(await page.locator('#physicalDetails').inputValue(),'');await invalid(page,lang);await page.locator('#physicalDetails').fill('QA RESTORED');await page.reload();await page.locator('[data-action="resume"]').click();assert.equal(await page.locator('#physicalDetails').inputValue(),'QA RESTORED');assert.equal(await page.locator('html').getAttribute('lang'),lang);assert.deepEqual(await data(page),{...before,physicalDetails:'QA RESTORED'});await page.locator('[data-action="back"]').click();assert.equal(await page.locator('#firstName').inputValue(),'QA');await page.locator('[data-action="next"]').click();assert.equal(await page.locator('#physicalDetails').inputValue(),'QA RESTORED');await page.locator('[name="physicalWork"][value="no"]').locator('..').click();await page.locator('[data-action="next"]').click();assert.equal(await page.locator('.progress-meta strong').innerText(),'3 / 3');assert.equal(await page.locator('.field-error').count(),0);assert.deepEqual(errors,[]);
  report.rows.push({width,lang,status:'passed',onlyPhysicalDetailsInvalid:true,step2:true,languageRoundTrip:true,previousErrorResetThenRevalidated:true,allOtherAnswersPreserved:true,nativeKeyboardTab:true,whitespaceRejected:true,clearedOnEdit:true,correctionToStep3:true,backPreserved:true,noClearsAndHides:true,yesRestartsEmpty:true,resumed:true,hiddenFieldNotRequired:true,noDelivery:true,dom});
 }catch(e){await page.screenshot({path:join(reportDir,`failure-physicalDetails-${width}-${lang}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
try{
 await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();const cases=[320,1280].flatMap(width=>Object.keys(messages).map(lang=>({width,lang})));let next=0;await Promise.all(Array.from({length:2},async()=>{while(next<cases.length)await run(cases[next++]);}));assert.equal(report.rows.length,40);const stable=report.captureGeometry.filter(x=>x.stable);assert.equal(stable.length,40);assert.equal(new Set(stable.map(x=>x.file)).size,40);assert.deepEqual(report.mutations,[]);report.applicationDeliveryAttempts=0;report.status='PASSED_40_CONDITIONAL_DETAILS_ERROR_KEYBOARD_AND_RECOVERY';
}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();report.finished=new Date().toISOString();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
